INSERT INTO motorcycle_models (id, name, brand, category, engine_cc, power_hp, cooling, fuel_system, price_dzd, image_url, description, is_active, created_at) VALUES ('3b2af5ef-3d15-4188-a1a0-af7e7c841740', 'VMS Driver 150', 'VMS', 'Maxi Scooter', 150, 13.5, 'Liquide', 'EFI Delphi', 365000, 'https://images.unsplash.com/photo-1568772585407-9361f9bf3a87?w=600&auto=format&fit=crop&q=80', 'Maxi-scooter racé avec freins ABS, éclairage full LED, tableau de bord TFT couleur et port USB de charge rapide.', TRUE, '2026-11-21T15:18:30.809439+00:00') ON CONFLICT (id) DO NOTHING;
